/** One recorded agent's body, as the native geometry path produced it. */
export interface NativeAgentBody {
  /** The agent's Number() — the `genome_<n>.txt.gz` it was read from. */
  readonly number: number;
  /** `agent::InitGeneCache()`'s `geneCache.size` (`fGenome->get( "Size" )`). */
  readonly size: number;
  /** `geneCache.maxSpeed` (`fGenome->get( "MaxSpeed" )`). */
  readonly maxSpeed: number;
  /** `agent::SetGeometry()`: `Size() / sqrt( geneCache.maxSpeed )`. */
  readonly lengthX: number;
  /** `agent::SetGeometry()`: `Size() * sqrt( geneCache.maxSpeed )`. */
  readonly lengthZ: number;
  /** `gpolyobj::setlen()`'s bounding box over the scaled mesh. */
  readonly lx: number;
  readonly ly: number;
  readonly lz: number;
  /** `agent::setradius()`: the collision radius (`fRadius`, and then `fCarryRadius`). */
  readonly radius: number;
  readonly carryRadius: number;
}

/** The `agent::config` values those bodies were computed with. (`maxRadius` and
 *  `globals::worldsize` are *not* here: the simulation, not the worldfile pipeline this
 *  probe runs, sets them — Simulation.cc:327/4012.) */
export interface NativeBodyConfig {
  readonly worldfile: string;
  readonly agentHeight: number;
  readonly minAgentSize: number;
  readonly maxAgentSize: number;
  readonly minMaxSpeed: number;
  readonly maxMaxSpeed: number;
}

